package com.osminog.vision;
import static org.junit.Assert.*;
import androidx.test.core.app.ActivityScenario;
import androidx.test.platform.app.InstrumentationRegistry;
import java.util.concurrent.*;
import java.util.concurrent.atomic.*;
import org.json.*;
import org.junit.*;

/** Real WebView/native UI. No fake live model/server is supplied. */
public class IntentUiTest {
 ActivityScenario<ReliableActivity> scenario;ReliableActivity a;
 interface Check{boolean ok()throws Exception;}
 void until(Check c)throws Exception{long end=System.currentTimeMillis()+10000;while(System.currentTimeMillis()<end){if(c.ok())return;Thread.sleep(60);}fail("Condition timeout");}
 void ui(Runnable r){InstrumentationRegistry.getInstrumentation().runOnMainSync(r);}
 String js(String script)throws Exception{CountDownLatch l=new CountDownLatch(1);AtomicReference<String> out=new AtomicReference<>();ui(()->a.shell.evaluateJavascript(script,v->{out.set(v);l.countDown();}));assertTrue(l.await(5,TimeUnit.SECONDS));return out.get();}
 void input(String text)throws Exception{js("document.getElementById('text').value="+JSONObject.quote(text)+";document.getElementById('text').dispatchEvent(new Event('input'))");}
 void send(String text)throws Exception{input(text);js("document.getElementById('eye').click()");until(()->"false".equals(js("busy")));}
 void actions()throws Exception{js("document.querySelector('.message.user .avatar').click()");}
 @Before public void start()throws Exception{scenario=ActivityScenario.launch(ReliableActivity.class);scenario.onActivity(x->a=x);until(()->"true".equals(js("!!window.OSMINOG?.nativeReady")));js("localStorage.removeItem('osminogPrivateOceanV1');localStorage.setItem('osminogMotion','off');localStorage.setItem('osminogWelcomed','1');localStorage.setItem('osminogTheme','blue');location.reload()");until(()->"true".equals(js("!!window.OSMINOG?.nativeReady&&!document.getElementById('welcomeScreen').offsetHeight")));}
 @After public void close(){if(scenario!=null)scenario.close();}
 @Test public void ordinaryMessageIsPrivateNotPublished()throws Exception{send("Привет");assertEquals("1",js("data.messages.length"));assertEquals("true",js("!data.messages[0].intent&&data.messages[0].delivery==='unavailable'"));assertEquals("0",js("document.querySelectorAll('.message.assistant').length"));}
 @Test public void messageBubbleHasAllActions()throws Exception{send("Привет");actions();assertEquals("true",js("document.getElementById('messageActions').open&&!!document.getElementById('editMessage')&&!!document.getElementById('deleteMessage')&&!!document.getElementById('publishMessage')"));}
 @Test public void editingKeepsIdentityAndDoesNotPublish()throws Exception{send("Первая версия");String id=js("data.messages[0].id");actions();js("document.getElementById('editMessage').click()");input("Новая версия");js("document.getElementById('eye').click()");assertEquals(id,js("data.messages[0].id"));assertEquals("true",js("data.messages.length===1&&data.messages[0].text==='Новая версия'&&!data.messages[0].intent"));}
 @Test public void cancelEditRestoresComposerDraft()throws Exception{send("Сообщение");input("Личный черновик");actions();js("document.getElementById('editMessage').click()");input("Изменение");js("document.getElementById('cancelEdit').click()");assertEquals("\"Личный черновик\"",js("document.getElementById('text').value"));}
 @Test public void deletionRequiresConfirmation()throws Exception{send("Удаляемое");actions();js("document.getElementById('deleteMessage').click()");assertEquals("1",js("data.messages.length"));js("document.getElementById('confirmNo').click()");assertEquals("1",js("data.messages.length"));actions();js("document.getElementById('deleteMessage').click();document.getElementById('confirmYes').click()");assertEquals("0",js("data.messages.length"));}
 @Test public void shortTapOnlyOpensAttachments()throws Exception{input("Черновик");js("document.getElementById('intentBubble').click()");assertEquals("true",js("document.getElementById('attachmentSheet').open&&data.messages.length===0"));}
 @Test public void holdPreparesIntentButNeverFakesPublication()throws Exception{input("Ищу ушанку");js("document.getElementById('intentBubble').dispatchEvent(new PointerEvent('pointerdown',{button:0,pointerId:1,clientX:25,clientY:40,bubbles:true}))");Thread.sleep(800);assertEquals("true",js("document.getElementById('confirmSheet').open"));js("document.getElementById('confirmYes').click()");until(()->"false".equals(js("busy")));assertEquals("true",js("data.messages.length===1&&data.messages[0].intent.state==='draft'&&document.querySelectorAll('.intent-published').length===0"));}
 @Test public void cancelledHoldDoesNotSend()throws Exception{input("Не отправлять");js("const b=document.getElementById('intentBubble');b.dispatchEvent(new PointerEvent('pointerdown',{button:0,pointerId:1,clientX:25,clientY:40}));b.dispatchEvent(new PointerEvent('pointercancel',{pointerId:1}))");Thread.sleep(800);assertEquals("0",js("data.messages.length"));}
 @Test public void intentFromAlreadySentMessageIsNotDuplicated()throws Exception{send("Ищу ушанку");actions();js("document.getElementById('publishMessage').click();document.getElementById('confirmYes').click()");until(()->"false".equals(js("busy")));assertEquals("true",js("data.messages.length===1&&data.messages[0].intent.state==='draft'"));}
 @Test public void staleAcknowledgementCannotPublishEditedText()throws Exception{send("Приватное");js("OSMINOG.receive({type:'delivery',action:'publish',id:data.messages[0].id,revision:0,ok:true,serverId:'fake-late-receipt'})");assertEquals("true",js("!data.messages[0].intent"));}
 @Test public void profileThemeAndNamePersist()throws Exception{js("document.getElementById('menu').click();document.getElementById('themeToggle').click();document.getElementById('profileName').value='Тест';document.getElementById('profileName').dispatchEvent(new Event('change'));location.reload()");until(()->"true".equals(js("!!window.OSMINOG?.nativeReady")));assertEquals("true",js("document.body.classList.contains('theme-dark')&&data.profile.name==='Тест'"));}
 @Test public void noFabricatedFollowersOrReplies()throws Exception{js("document.getElementById('menu').click()");assertEquals("\"0\"",js("document.getElementById('subscriptionCount').textContent"));assertEquals("\"0\"",js("document.getElementById('intentionCount').textContent"));}
 @Test public void nativeNavigationInsetProtectsEye()throws Exception{ui(()->a.applyInsets(24,48));Thread.sleep(200);assertEquals("true",js("document.getElementById('eye').getBoundingClientRect().bottom<=innerHeight-48"));}
 @Test public void welcomeAlsoRespectsBottomInset()throws Exception{js("localStorage.removeItem('osminogWelcomed');location.reload()");until(()->"true".equals(js("!!window.OSMINOG?.nativeReady")));ui(()->a.applyInsets(24,48));Thread.sleep(200);assertEquals("true",js("document.getElementById('welcomeWake').getBoundingClientRect().bottom<=innerHeight-48"));}
 @Test public void languageCanChangeAfterOnboarding()throws Exception{js("document.getElementById('menu').click();document.getElementById('languageButton').click();document.querySelectorAll('#languageOptions button')[5].click()");assertEquals("\"ar\"",js("localStorage.getItem('osminogLanguage')"));}
 @Test public void oldHistoryRemainsAccessibleAndPrivate()throws Exception{js("localStorage.setItem('osminogVisionHistoryV2',JSON.stringify({'0':[{role:'user',text:'OLD_PRIVATE_SENTINEL'}]}));location.reload()");until(()->"true".equals(js("!!window.OSMINOG?.nativeReady")));js("document.getElementById('menu').click();document.getElementById('archiveButton').click()");assertEquals("true",js("document.getElementById('archiveMessages').textContent.includes('OLD_PRIVATE_SENTINEL')&&data.messages.length===0"));}
 @Test public void retiredProviderScriptAbsent()throws Exception{boolean absent=false;try{a.getAssets().open("provider.js").close();}catch(java.io.IOException expected){absent=true;}assertTrue(absent);assertEquals("false",js("!!document.getElementById('providerSheet')"));}
 @Test public void updaterStillRejectsUntrustedAssets(){assertTrue(Updater.assetUrl("https://github.com/jeep-jim/OSMINOG-Releases/releases/download/vision-android-v0.2.6/OSMINOG.apk"));assertFalse(Updater.assetUrl("https://evil.example/osminog.apk"));assertFalse(Updater.assetUrl("http://github.com/jeep-jim/OSMINOG-Releases/releases/download/vision-android-v0.2.6/a.apk"));}
 @Test public void localMessagesSurviveReloadWithoutResend()throws Exception{send("Сохрани");js("location.reload()");until(()->"true".equals(js("!!window.OSMINOG?.nativeReady")));assertEquals("true",js("data.messages.length===1&&!busy&&data.messages[0].delivery==='unavailable'"));}
 @Test public void fullProfileCanBeCaptured()throws Exception{js("document.getElementById('menu').click()");Thread.sleep(200);try(java.io.FileOutputStream f=new java.io.FileOutputStream("/sdcard/vision-menu.png")){InstrumentationRegistry.getInstrumentation().getUiAutomation().takeScreenshot().compress(android.graphics.Bitmap.CompressFormat.PNG,100,f);}js("document.getElementById('closeMenu').click()");send("Привет, что ты такое? =)))");js("document.getElementById('dismiss').click()");Thread.sleep(200);try(java.io.FileOutputStream f=new java.io.FileOutputStream("/sdcard/vision-home.png")){InstrumentationRegistry.getInstrumentation().getUiAutomation().takeScreenshot().compress(android.graphics.Bitmap.CompressFormat.PNG,100,f);}}
}
